    status: response.status,
    member,
    firstChunkHasFrame: initial.includes('<h1>Workspace</h1>') && initial.includes('12<"'!-- --> active projects'"'),
    firstChunkHasFallback: initial.includes('Loading your workspace details'),
    hasOwnDetails: html.includes("'`Welcome, <!-- -->${member}`) && html.includes(`Team: <!-- -->${team}`) && html.includes(`Region: <!-- -->${region}`),
    hasOtherMember: html.includes(`Welcome, <!-- -->${other}`),
  }))
}
EOF'
